import java.util.*;

 public class main{
  static int dp[][] ;

  static int lca(int i , int j , String s1 , String s2)
  {
  if(i<0 || j<0 ) return 0 ;
  if(dp[i][j]!= -1 ) return dp[i][j] ;

  if(s1.charAt(i)==s2.charAt(j) ){
  dp[i][j] = 1 + lca(i-1 , j-1 , s1 , s2) ;
  }

  else {
  dp[i][j] = Math.max( lca(i-1 , j, s1,s2) , lca(i,j-1 , s1,s2 ) ) ;
  }

  return dp[i][j] ;
  }



  public static void main(String args[]){
  Scanner sc = new Scanner(System.in) ;
  String s ;
  s = sc.nextLine() ;

  StringBuilder ts2 = new StringBuilder(s); 
 ts2.reverse();
 String s2 = ts2.toString();

  int n = s.length(); 

  dp = new int[n+1][n+1] ;
  for(int i = 0 ; i<n ; i++)
  {
  for(int j = 0 ; j<n ; j++)
  {
  dp[i][j] = -1 ;
  }
  }

  int result = lca(n-1 , n-1 , s,s2) ;
  System.out.println(n-result) ;





  }
 }

