 public class main{
  static int[] v ;
  static int [] w ;
  static int dp[][] ;
  static int ar[] ;
 /////////

 static void knap (int n , int W){


  for(int i = 0 ; i<=n ; i++){

  for(int j = 0 ; j<= W; j++){

  if(i== 0 || j== 0 ){
  dp[i][j] = 0 ;
  }

  else if(w[i-1] <= j ){

  int in = v[i-1] + dp[i-1][ j - w[i-1] ] ;
  int out = dp[i-1][j] ;

  if(in > out)
  {
  ar[i] = 1 ;
  }

  dp[i][j] = Math.max(in , out ) ;

  }
  else {
  dp[i][j] = dp[i-1][j];
  }
  }
  }


 }

